def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remainder = np.mod(bins, item)
    return np.where(bins >= item, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, -rem, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    counts = np.floor_divide(bins, item)
    return np.where(bins >= item, counts, -np.inf)
